package org.sleepwell.app;

import org.json.*;
import java.util.*;

final class ChallengeRoutineJson {
    static JSONArray encode(ChallengeRoutine routine){JSONArray array=new JSONArray();try{for(ChallengeRoutine.Task task:routine.tasks){JSONObject row=new JSONObject().put("type",task.type).put("rounds",task.rounds);if(task.type.equals("Walk"))row.put("steps",task.targetSteps);if(task.type.equals("Math")&&!task.math.equals(MathSettings.LEGACY))row.put("math",MathSettingsJson.encode(task.math));array.put(row);}}catch(JSONException impossible){throw new IllegalStateException(impossible);}return array;}
    static ChallengeRoutine decode(JSONArray array)throws JSONException{if(array==null)throw new JSONException("Missing challenge routine");List<ChallengeRoutine.Task> tasks=new ArrayList<>();if(array.length()>ChallengeRoutine.LIMIT)throw new JSONException("Too many challenge tasks");try{for(int n=0;n<array.length();n++){JSONObject task=array.getJSONObject(n);Object type=task.get("type"),rounds=task.get("rounds");if(!(type instanceof String)||!(rounds instanceof Number))throw new JSONException("Challenge type must be text and rounds must be an integer");double count=((Number)rounds).doubleValue();if(!Double.isFinite(count)||count!=Math.rint(count)||count<1||count>6)throw new JSONException("Challenge rounds must be an integer from 1 to 6");int target=0;if(type.equals("Walk")){Object steps=task.get("steps");if(!(steps instanceof Number)||!Double.isFinite(((Number)steps).doubleValue())||((Number)steps).doubleValue()!=Math.rint(((Number)steps).doubleValue()))throw new JSONException("Walk steps must be an integer");double value=((Number)steps).doubleValue();if(value<5||value>100)throw new JSONException("Choose 5–100 steps");target=(int)value;}MathSettings math=MathSettings.LEGACY;if(task.has("math")){if(!type.equals("Math"))throw new JSONException("Arithmetic settings belong only to a Math task");math=MathSettingsJson.decode(task.get("math"));}tasks.add(new ChallengeRoutine.Task((String)type,(int)count,target,math));}return new ChallengeRoutine(tasks);}catch(IllegalArgumentException error){throw new JSONException(error.getMessage());}}
}
